Voici une fonction en JavaScript qui vérifie si un nombre donné dans un tableau est un nombre premier valide et imprime celui-ci sur la console :

```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (num < 2) continue;
    let isPrime = true;
    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      console.log(`Le nombre premier est : ${num}`);
      return;
    }
  }
}

